9	/**
10	 * Extracts the consultant's available open days from Tableau worksheet rows.
11	 * Looks for a column whose name contains "open" (case-insensitive) in the first row.
12	 * Returns null if the column is absent, the value is non-numeric, or rows are empty.
13	 * Column naming convention: "Open Days", "open_days", "Available Days", etc.
14	 */
15	export function extractAvailableDays(rows: WorksheetRow[], columnName?: string | null): number | null {
16	  if (rows.length === 0) return null;
17	  const row = rows[0];
18	  let key: string | undefined;
19	  if (columnName) {
20	    key = Object.keys(row).find((k) => k.toLowerCase() === columnName.toLowerCase());
21	  } else {
22	    key = Object.keys(row).find((k) => k.toLowerCase().includes('open'));
23	  }
24	  if (!key) return null;
25	  const val = parseFloat(row[key]);
26	  return isNaN(val) ? null : val;
27	}
28	
29	/**
30	 * Returns rows where row[availabilityColumn] matches availabilityValue (case-insensitive).
31	 * Returns empty array when column/value are not provided or no rows match.
32	 */
33	export function extractAvailableRows(
34	  rows: WorksheetRow[],
35	  availabilityColumn: string | null,
36	  availabilityValue: string | null
37	): WorksheetRow[] {
38	  if (!availabilityColumn || !availabilityValue) return [];
39	  return rows.filter((row) => {
40	    const key = Object.keys(row).find((k) => k.toLowerCase() === availabilityColumn.toLowerCase());
41	    if (!key) return false;
42	    return String(row[key]).toLowerCase() === availabilityValue.toLowerCase();
43	  });
44	}
