46	class DataStore {
47	  // Tableau worksheet panel
48	  worksheetRows = $state<WorksheetRow[]>([]);
49	  worksheetState = $state<DataLoadState>('idle');
50	  worksheetError = $state<string | null>(null);
51	
52	  // Consultant's available open days — extracted from worksheetRows on load.
53	  // null when Tableau data is unavailable (triggers graceful capacity check failure).
54	  availableDays = $state<number | null>(null);
55	
56	  // Rows the consultant has selected from the DataPanel for context_selection.
57	  selectedRows = $state<WorksheetRow[]>([]);
58	
59	  // Google Docs task list panel
60	  tasks = $state<TaskItem[]>([]);
61	  tasksState = $state<DataLoadState>('idle');
62	  tasksError = $state<string | null>(null);
63	}
64	
65	export const dataStore = new DataStore();
